  "--ha-success":["--success-color"],
  "--ha-error":["--error-color"],
  "--ha-warning":["--warning-color"],
  "--ha-radius":["--ha-card-border-radius"],
  "--ha-card-shadow":["--ha-card-box-shadow"],
  "--ha-card-border":["--ha-card-border-color"],
  "--ha-card-border-w":["--ha-card-border-width"],
