function slOpaque(c){if(!c)return false;c=c.trim();if(!c||c==="transparent")return false;const m=c.match(/rgba?\(([^)]+)\)/);if(m){const p=m[1].split(/[ ,\/]+/).filter(Boolean);return p.length<4||parseFloat(p[3])>=0.98}if(/^#([0-9a-f]{4}|[0-9a-f]{8})$/i.test(c)){const h=c.slice(1);const a=h.length===4?h[3]+h[3]:h.slice(6,8);return parseInt(a,16)>=250}return true}
